update takes ~1 minute on prelive, so will run it batched:

{noformat}USE taxify_fraud;
DROP PROCEDURE IF EXISTS update_3950;

DELIMITER $$
CREATE PROCEDURE update_3950()
BEGIN


  DECLARE v_min_id, v_max_id BIGINT;
  DECLARE v_batch_size INT DEFAULT 500;

  DECLARE v_sleep_cnt INT DEFAULT 0;
  DECLARE v_sleep_after INT DEFAULT 200;
  DECLARE v_sleep_time INT DEFAULT 3;

  SELECT MIN(id), MAX(id) INTO v_min_id, v_max_id FROM `taxify_fraud`.`user_payment_adding_attempt`;
  SELECT v_min_id, v_max_id, v_batch_size;

  WHILE v_min_id <= v_max_id DO

    UPDATE `taxify_fraud`.`user_payment_adding_attempt` SET expires=NULL
    WHERE id >= v_min_id AND id < v_min_id + v_batch_size AND expires=0;

    SET v_min_id = v_min_id + v_batch_size;

    SET v_sleep_cnt = v_sleep_cnt + 1;
    SELECT v_min_id, v_sleep_cnt, v_sleep_after;

    IF v_sleep_cnt > v_sleep_after THEN
      SELECT CONCAT('Sleeping ', v_sleep_time, ' sec');
      SELECT SLEEP(v_sleep_time);
      SET v_sleep_cnt = 0;
    END IF;

  END WHILE;
END;
$$
DELIMITER ;

CALL update_3950();

DROP PROCEDURE IF EXISTS update_3950;{noformat}

