DELIMITER $$
CREATE PROCEDURE update_in_loop_3992_2()
BEGIN


  DECLARE v_min_id, v_max_id BIGINT;
  DECLARE v_batch_size INT DEFAULT 200;

  DECLARE v_sleep_cnt INT DEFAULT 0;
  DECLARE v_sleep_after INT DEFAULT 1000;
  DECLARE v_sleep_time INT DEFAULT 5;

  SELECT MIN(id), MAX(id) INTO v_min_id, v_max_id FROM `taxify_invoicing2`.`user_invoice`;
  SELECT v_min_id, v_max_id, v_batch_size;

  WHILE v_min_id <= v_max_id DO

    UPDATE `taxify_invoicing2`.`user_invoice` SET `order_ride_start` = `order_created`,`last_update` = `last_update`
    WHERE id >= v_min_id AND id < v_min_id + v_batch_size AND `order_ride_start` = 0;

	UPDATE `taxify_invoicing2`.`user_invoice` SET `order_ride_end` = `created`,`last_update` = `last_update`
    WHERE id >= v_min_id AND id < v_min_id + v_batch_size AND `order_ride_end` = 0;

    SET v_min_id = v_min_id + v_batch_size;

    SET v_sleep_cnt = v_sleep_cnt + 1;
    SELECT v_min_id, v_sleep_cnt, v_sleep_after;

    IF v_sleep_cnt > v_sleep_after THEN
      SELECT CONCAT('Sleeping ', v_sleep_time, ' sec');
      SELECT SLEEP(v_sleep_time);
      SET v_sleep_cnt = 0;
    END IF;

  END WHILE;
END;
$$
DELIMITER ;

CALL update_in_loop_3992_2();

DROP PROCEDURE IF EXISTS update_in_loop_3992_2;
