As direct update runs unacceptably long, batching is required:



{code:sql}# using id
USE taxify_fleet;
DROP PROCEDURE IF EXISTS update_in_loop_4381;

DELIMITER $$
CREATE PROCEDURE update_in_loop_4381()
BEGIN


  DECLARE v_min_id, v_max_id BIGINT;
  DECLARE v_batch_size INT DEFAULT 200;

  DECLARE v_sleep_cnt INT DEFAULT 0;
  DECLARE v_sleep_after INT DEFAULT 1000;
  DECLARE v_sleep_time INT DEFAULT 5;

  SELECT MIN(id), MAX(id) INTO v_min_id, v_max_id FROM `taxify_fleet`.`driver`;
  SELECT v_min_id, v_max_id, v_batch_size;

  WHILE v_min_id <= v_max_id DO

    UPDATE `taxify_fleet`.`driver` SET `sync_insurance_provider_id` = NULL
    WHERE id >= v_min_id AND id < v_min_id + v_batch_size AND `sync_insurance_provider_id` = 0;

    SET v_min_id = v_min_id + v_batch_size;

    SET v_sleep_cnt = v_sleep_cnt + 1;
    SELECT v_min_id, v_sleep_cnt, v_sleep_after;

    IF v_sleep_cnt > v_sleep_after THEN
      SELECT CONCAT('Sleeping ', v_sleep_time, ' sec');
      SELECT SLEEP(v_sleep_time);
      SET v_sleep_cnt = 0;
    END IF;

  END WHILE;
END;
$$
DELIMITER ;

CALL update_in_loop_4381();

DROP PROCEDURE IF EXISTS update_in_loop_4381;{code}

