We send jailbreak boolean flag when driver logs in. It is sent via {{driverPhoneDetails}} endpoint in {{51}} field of request body.
Here is the code we are using currently

{noformat}public var isJailbroken: Bool {
        if TARGET_IPHONE_SIMULATOR != 1 {
            // Check 1 : existence of files that are common for jailbroken devices
            if FileManager.default.fileExists(atPath: "/Applications/Cydia.app")
                || FileManager.default.fileExists(atPath: "/Library/MobileSubstrate/MobileSubstrate.dylib")
                || FileManager.default.fileExists(atPath: "/bin/bash")
                || FileManager.default.fileExists(atPath: "/usr/sbin/sshd")
                || FileManager.default.fileExists(atPath: "/etc/apt")
                || FileManager.default.fileExists(atPath: "/private/var/lib/apt/")
                || UIApplication.shared.canOpenURL(URL(string: "cydia://package/com.example.package")!) {
                return true
            }
            // Check 2 : Reading and writing in system directories (sandbox violation)
            let stringToWrite = "Jailbreak Test"
            do {
                try stringToWrite.write(toFile: "/private/JailbreakTest.txt", atomically: true, encoding: String.Encoding.utf8)
                //Device is jailbroken
                return true
            } catch {
                return false
            }
        } else {
            return false
        }
    }{noformat}

{quote}*Clause 5.5* indicates that Bolt will not provide tech support – please can this be removed, or either reworded to indicate that Bolt will not provide tech support for the tech infrastructure supporting the Bolt platform? I understand that Bolt cannot be liable for ensuring that supporting infrastructure like wi-fi, tablet, browser, etc. are working, but the current wording is vague and implies that Bolt will not be responsible for any tech support on the Bolt platform – surely Bolt needs to provide tech support for their own platform if there is an issue? 

{color:#36b37e}Happy from my side that we amend to along the lines of “Bolt will not provide tech support for the tech infrastructure supporting the Bolt platform”. If there is a tech issue, we do assist in solving it. e.g. tablet, updates.{color}

{color:#36b37e}I think the point we are trying to make is that it is the providers responsibility to update the tablet when new software updates are available - and we won’t provide support if they don't.{color}

{color:#36b37e}I don't see meaningful potential liability here. {color}

Re. the customer complaints process outlined in *clause 5.7 –* our current process with Uber is that we are able to access and manage this directly on their partner platform, rather than having Uber issue refunds and deduct this automatically. We are more than happy to take ownership of managing product complaints, so wanted to check whether Bolt is able to facilitate a similar process, and how this will work?{quote}

{color:#36b37e}This is not supported/automated by our platform. For the trial period, happy that we share any proposed refunds with RF before they are processed - a manual workarounds. After trial we should reassess. {color}

{code:sql}USE taxify_delivery_order;
DROP PROCEDURE if exists update_in_loop;

DELIMITER $$
CREATE PROCEDURE update_in_loop()
BEGIN

DECLARE v_min_id, v_max_id BIGINT;
DECLARE v_batch_size INT DEFAULT 2000;
#DECLARE v_sleep_cnt INT DEFAULT 0;
#DECLARE v_sleep_after INT DEFAULT 100;
#DECLARE v_sleep_time INT DEFAULT 10;

SELECT MIN(id), MAX(id) INTO v_min_id, v_max_id FROM `taxify_delivery_order`.`order`;
SELECT v_min_id, v_max_id, v_batch_size; 

WHILE v_min_id <= v_max_id DO

UPDATE 
	`taxify_delivery_order`.`order` o
    JOIN `taxify_delivery_order`.`order_provider` op ON op.order_id = o.id AND op.retry_to_order_provider_id is NULL
	JOIN `taxify_delivery_order`.`order_courier` oc ON oc.order_provider_id = op.id AND oc.retry_to_order_courier_id is NULL
SET
	o.last_active_courier_id = oc.courier_id,
	o.last_active_courier_phone = oc.phone,
    o.last_update = o.last_update
WHERE
    o.id >= v_min_id AND o.id < v_min_id + v_batch_size AND o.last_active_courier_id IS NULL;

SET v_min_id = v_min_id + v_batch_size;
#SET v_sleep_cnt = v_sleep_cnt + 1;
SELECT v_min_id, /*v_sleep_cnt,*/ v_min_id*100/v_max_id as done;

#IF v_sleep_cnt > v_sleep_after THEN
#  SELECT CONCAT('Sleeping ', v_sleep_time, ' sec');
#  SELECT SLEEP(v_sleep_time);
#  SET v_sleep_cnt = 0;
#END IF;

END WHILE;

END;
$$
DELIMITER ;

CALL update_in_loop();

